pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 burnAmount) public {
        vm.assume(burnAmount <= c.totalSupply());
        address originalOwner = c.owner();
        vm.prank(originalOwner);
        c.owned();
        vm.prank(originalOwner);
        bool ok;
        try c.burn(burnAmount) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
